// The bindings and secrets the Worker uses. Written by hand rather than generated by `wrangler types`
// (docs/decisions.md); the handler still parses `env` before trusting any of it.
declare namespace Cloudflare {
  interface Env {
    /** AUTH-1: the Access team domain, `https://<team>.cloudflareaccess.com`; checked by `parseConfig` (config.ts). */
    ACCESS_TEAM_DOMAIN: string;
    /** AUTH-1: the Access application's audience tag; checked by `parseConfig` (config.ts). */
    ACCESS_AUD: string;
    /** RES-2, RES-3: the stored translations (worker/migrations/); checked by `handleTranslate` (translate.ts). */
    DB: D1Database;
    /** KEY-2: each provider's key, optional; a provider without one answers `no-api-key` (translate.ts). */
    DEEPSEEK_API_KEY?: string;
    OPENAI_API_KEY?: string;
    GEMINI_API_KEY?: string;
    /**
     * KEY-5: the owner's GitHub token for the scheduled translation, a fine-grained token with read-only pull requests;
     * checked by `parseScheduledConfig` (scheduled-config.ts). A secret.
     */
    GITHUB_TOKEN?: string;
    /**
     * PRIV-1: private repositories the schedule may translate, `owner/repo` separated by commas or spaces; empty means
     * none. A secret, as it names private repositories. Checked by `parseScheduledConfig`.
     */
    PRIVATE_REPOSITORIES?: string;
    /** The schedule's CEL filter (filter.ts); empty means every pull request that passes PRIV-1. A variable. */
    AHEAD_OF_TIME_FILTER?: string;
    /** The schedule's choice, `provider/model/thinking`; empty means the extension's default. A variable. */
    AHEAD_OF_TIME_CHOICE?: string;
  }

  interface GlobalProps {
    // Types `exports` from `cloudflare:workers` in the tests.
    mainModule: typeof import("./index.ts");
  }
}
interface Env extends Cloudflare.Env {}
